import unittest
from manifest_csv import load_manifest

class ManifestRows(unittest.TestCase):
    def test_implicit_header_and_ragged_rows(self):
        self.assertEqual(load_manifest('sku,site,qty\nA7,west,4\nB8,east\nC9,north,8,fragile,cold\n'), [
            {'sku': 'A7', 'site': 'west', 'qty': '4'},
            {'sku': 'B8', 'site': 'east', 'qty': None},
            {'sku': 'C9', 'site': 'north', 'qty': '8', 'overflow': ['fragile', 'cold']},
        ])

    def test_explicit_names_keep_first_row(self):
        self.assertEqual(load_manifest('D2,south\nE3,central,hold\n', ['sku', 'site']), [
            {'sku': 'D2', 'site': 'south'},
            {'sku': 'E3', 'site': 'central', 'overflow': ['hold']},
        ])

    def test_missing_versus_explicit_empty(self):
        self.assertEqual(load_manifest('sku,site\nA7,\nB8\n'), [
            {'sku': 'A7', 'site': ''}, {'sku': 'B8', 'site': None}])
        self.assertEqual(load_manifest('sku,site\n'), [])
        self.assertEqual(load_manifest(''), [])

    def test_blank_records_and_quoted_fields(self):
        self.assertEqual(load_manifest('sku,site\n\nA7,"bay, east"\n'),
                         [{'sku': 'A7', 'site': 'bay, east'}])
        self.assertEqual(load_manifest('A7,west\n', []),
                         [{'overflow': ['A7', 'west']}])

if __name__ == '__main__':
    unittest.main()

